# generate 8 linear transforms of grid coords: rotations/reflections

def raw_transforms(pt):
    r,c=pt
    return [(r,c),(r,-c),(-r,c),(-r,-c),(c,r),(c,-r),(-c,r),(-c,-r)]

def orient_shape(coords, marker=None):
    out=[]
    for ti in range(8):
        pts=[raw_transforms(p)[ti] for p in coords]
        mrmc=raw_transforms(marker)[ti] if marker is not None else None
        minr=min(r for r,c in pts); minc=min(c for r,c in pts)
        norm={(r-minr,c-minc) for r,c in pts}
        mnorm=(mrmc[0]-minr,mrmc[1]-minc) if marker is not None else None
        # dedup orientation by shape and marker
        if not any(o[0]==norm and o[1]==mnorm for o in out): out.append((norm,mnorm,ti))
    return out
for k,p in parts.items():
    print(k,len(orient_shape(p,Amarker if k=='A' else None)),[(x[1],x[2]) for x in orient_shape(p,Amarker if k=='A' else None)] if k=='A' else '')

H=W=14
boardmask=(1<<(H*W))-1

def encode(pts):
    return sum(1<<(r*W+c) for r,c in pts)

def placements_for(k):
    outs=orient_shape(parts[k],Amarker if k=='A' else None)
    candidates=[]
    for norm,mnorm,ti in outs:
        if k=='A':
            if mnorm!=(0,0): continue
            offsets=[(0,0)]
        else:
            maxr=max(r for r,c in norm); maxc=max(c for r,c in norm)
            offsets=[(dr,dc) for dr in range(H-maxr) for dc in range(W-maxc)]
        for dr,dc in offsets:
            pts={(r+dr,c+dc) for r,c in norm}
            if all(0<=r<H and 0<=c<W for r,c in pts):
                candidates.append({'piece':k,'ti':ti,'dr':dr,'dc':dc,'pts':pts,'mask':encode(pts)})
    return candidates
pcands={k:placements_for(k) for k in parts}
{k:len(v) for k,v in pcands.items()}

bycell={k:[[] for _ in range(H*W)] for k in parts}
for k,cs in pcands.items():
    for cand in cs:
        for p in cand['pts']:
            bycell[k][p[0]*W+p[1]].append(cand)
# find up to solutions
solutions=[]; nodes=0

def solve_exact(selected, covered, remaining, lim=5):
    global nodes
    nodes+=1
    if not remaining:
        if covered==boardmask:
            solutions.append(selected.copy())
            return len(solutions)>=lim
        return False
    # enumerate uncovered cells with smallest viable support, use list
    unc=[i for i in range(H*W) if not (covered>>i)&1]
    best=None; opts_best=None
    for i in unc:
        opts=[]
        bit=1<<i
        for k in remaining:
            for ca in bycell[k][i]:
                if ca['mask'] & covered == 0:
                    opts.append((k,ca))
        if best is None or len(opts)<len(opts_best):
            best=i; opts_best=opts
            if len(opts)==0: return False
            if len(opts)==1: break
    # Avoid duplicate ordering? choose cell forces it
    for k,ca in opts_best:
        newrem=tuple(x for x in remaining if x!=k)
        selected[k]=ca
        if solve_exact(selected, covered|ca['mask'], newrem, lim): return True
        selected.pop(k,None)
    return False
# constrain A candidates
for aa in pcands['A']:
    nodes=0
    solve_exact({'A':aa},aa['mask'],tuple(k for k in parts if k!='A'),10)
    print('A orient',aa['ti'],'nodes',nodes,'sols',len(solutions))
    if solutions:break

